package com.comfymobile.app;
import org.json.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;

public final class AnimeWorkflowTest {
 static void check(boolean pass,String message){if(!pass)throw new AssertionError(message);}
 static final class Capture implements BatchEngine.Transport {JSONObject body;boolean done;public JSONObject post(JSONObject j,String path,JSONObject body){this.body=body;return new JSONObject().put("prompt_id","anime-prompt");}public JSONObject get(JSONObject j,String path)throws Exception{if(path.equals("/queue"))return new JSONObject().put("queue_running",new JSONArray().put(new JSONArray().put(1).put("anime-prompt"))).put("queue_pending",new JSONArray());if(!done)return new JSONObject();return new JSONObject().put("anime-prompt",new JSONObject().put("status",new JSONObject().put("completed",true).put("status_str","success")).put("outputs",new JSONObject().put(j.getString("output"),new JSONObject().put("images",new JSONArray().put(new JSONObject().put("filename","anime.png").put("subfolder","").put("type","output"))))));}public String upload(JSONObject j,JSONObject f){throw new AssertionError("anime must never upload source images");}public JSONObject cache(JSONObject j,String p,String id)throws Exception{return new JSONObject().put("id",id).put("src","images/"+id).put("width",256).put("height",256);}}
 public static void main(String[] args)throws Exception{JSONObject all=new JSONObject(new String(Files.readAllBytes(Paths.get("assets/workflows.json")),StandardCharsets.UTF_8));for(String variant:new String[]{"base","turbo"}){BatchStore store=new BatchStore(Files.createTempDirectory("anime-model-").resolve("state.json").toFile());JSONObject job=BatchEngineTest.job(1,"anime","anima");job.getJSONObject("batch").getJSONObject("params").put("animaModel",variant).put("artistOption","WLOP · wlop");store.start(job);Capture net=new Capture();BatchEngine engine=new BatchEngine(store,net,all);engine.tick("anime");JSONObject prompt=net.body.getJSONObject("prompt");check(prompt.getJSONObject("44").getJSONObject("inputs").getString("unet_name").equals(variant.equals("base")?"anima-base-v1.0.safetensors":"anima-turbo-v1.1.safetensors"),"model filename mapping");check(prompt.getJSONObject("19").getJSONObject("inputs").getInt("steps")== (variant.equals("base")?32:10),"sampler steps preset");check(prompt.getJSONObject("19").getJSONObject("inputs").getDouble("cfg")== (variant.equals("base")?4:1),"sampler CFG preset");check(prompt.getJSONObject("51").getJSONObject("inputs").getString("text").equals("水彩小屋"),"positive enters translator glossary");check(prompt.getJSONObject("12").getJSONObject("inputs").getString("text").equals("模糊"),"negative stays independent");check(prompt.getJSONObject("58").getJSONObject("inputs").getString("artist").equals("WLOP · wlop"),"selected artist mapping");check(prompt.getJSONObject("11").getJSONObject("inputs").getJSONArray("text").getString(0).equals("58"),"translated prompt remains connected through artist node");check(store.hasWork(),"anime mode included in background scheduling");net.done=true;engine.tick("anime");JSONObject image=store.snapshot().getJSONArray("images").getJSONObject(0);check(image.getString("mode").equals("anime")&&image.getString("animaModel").equals(variant)&&image.getString("artistOption").equals("WLOP · wlop"),"anime gallery metadata");check(!store.hasWork(),"completed anime job ends foreground work");}
 for(String workflow:new String[]{"text","single","dual"}){JSONObject map=all.getJSONObject(workflow),p=map.getJSONObject("prompt"),positive=p.getJSONObject(map.getString("positive"));check(positive.getString("class_type").equals("ExcelPromptGlossary"),"existing workflow translated input mapping");check(positive.getJSONObject("inputs").getString("excel_path").replace('\\','/').contains("user/default/glossaries/Anima角色作品词典.xlsx"),"updated workbook path");check(Files.isRegularFile(Paths.get("../computer").resolve(positive.getJSONObject("inputs").getString("rules_path"))),"current rules file exists");}System.out.println("PASS: anime base/turbo filenames and 32/4 vs 10/1 presets, translator and artist mapping, independent negative input, background slot, gallery metadata and updated dictionary/rules paths");}
}
